#!/usr/bin/env node
// Generated by claude-kit. Context snapshots across compaction.
//   PostCompact            → saves the compaction summary to .claude/context/snapshots/ (git-ignored)
//   SessionStart (compact) → re-injects .claude/context/task_context.md so the task state survives compaction
// Compaction rebuilds the prompt cache anyway, so re-injecting here costs no extra cache misses.
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const SNAPSHOT_DIR = '.claude/context/snapshots';
const TASK_CONTEXT = '.claude/context/task_context.md';
const KEEP = 10;
/** Template placeholder lines start with "_"; a file with only those carries no state. */
const PLACEHOLDER = /^\s*(?:[-\d.]+\s*)?_.*_\s*$/;

function readInput() {
  try {
    return JSON.parse(fs.readFileSync(0, 'utf8'));
  } catch {
    return {};
  }
}

function hasRealContent(text) {
  return text
    .replace(/<!--[\s\S]*?-->/g, '')
    .split('\n')
    .some((l) => l.trim() && !l.startsWith('#') && !PLACEHOLDER.test(l));
}

function saveSnapshot(root, input) {
  const summary = typeof input.compact_summary === 'string' ? input.compact_summary.trim() : '';
  if (!summary) return;
  const dir = path.join(root, SNAPSHOT_DIR);
  fs.mkdirSync(dir, { recursive: true });
  const ignore = path.join(dir, '.gitignore');
  if (!fs.existsSync(ignore)) fs.writeFileSync(ignore, '*\n');

  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const session = String(input.session_id || 'session').slice(0, 8);
  const body = `# Compaction snapshot\n\n- session: ${input.session_id || 'unknown'}\n- trigger: ${input.trigger || 'unknown'}\n\n${summary}\n`;
  fs.writeFileSync(path.join(dir, `${stamp}-${session}.md`), body);
  fs.writeFileSync(path.join(dir, 'latest.md'), body);

  const old = fs
    .readdirSync(dir)
    .filter((f) => f.endsWith('.md') && f !== 'latest.md')
    .sort()
    .slice(0, -KEEP);
  for (const f of old) fs.rmSync(path.join(dir, f), { force: true });
}

function reinject(root) {
  const file = path.join(root, TASK_CONTEXT);
  let text;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch {
    return;
  }
  if (!hasRealContent(text)) return;
  process.stdout.write(
    `Task state from ${TASK_CONTEXT} (kept across compaction):\n\n${text.trim()}\n`,
  );
}

function main() {
  const input = readInput();
  const root = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
  try {
    if (input.hook_event_name === 'PostCompact') saveSnapshot(root, input);
    else if (input.hook_event_name === 'SessionStart') reinject(root);
  } catch (err) {
    process.stderr.write(`claude-kit snapshot hook: ${err && err.message}\n`);
  }
  return 0; // never block Claude over a snapshot
}

process.exit(main());
